// Fixed, integrity-protected eval battery for the autoresearch loop.
// Each task seeds a scratch workspace, is solved by the real harness `run` loop,
// and is graded deterministically. Do not edit this file from the loop.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { join } from 'node:path';

async function w(dir, rel, content) {
  const full = join(dir, rel);
  await mkdir(join(full, '..'), { recursive: true });
  await writeFile(full, content, 'utf8');
}

async function readMaybe(dir, rel) {
  try {
    return await readFile(join(dir, rel), 'utf8');
  } catch {
    return null;
  }
}

async function runsClean(dir, cmd, execFileP) {
  try {
    await execFileP('bash', ['-lc', cmd], { cwd: dir });
    return true;
  } catch {
    return false;
  }
}

export const TASKS = [
  {
    name: 'fix_failing_test',
    maxTurns: 10,
    prompt:
      "The test suite in this workspace is failing. Run 'npm test' with the bash tool, find the bug in src/math.js, fix it so add() adds, and make all tests pass. Do not edit test files.",
    async setup(dir) {
      await w(dir, 'package.json', JSON.stringify({ name: 'e', type: 'module', scripts: { test: 'node --test test/*.test.js' } }) + '\n');
      await w(dir, 'src/math.js', 'export function add(a, b) {\n  return a - b;\n}\n');
      await w(dir, 'test/math.test.js', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { add } from '../src/math.js';\ntest('adds', () => { assert.equal(add(2,3),5); assert.equal(add(10,5),15); });\n");
    },
    async grade(dir, execFileP) {
      return runsClean(dir, 'npm test', execFileP);
    },
  },
  {
    name: 'implement_spec',
    maxTurns: 10,
    prompt:
      "Implement reverse(s) in src/strings.js so it returns the input string reversed and all tests in test/strings.test.js pass. Run 'npm test' to verify. Do not edit test files.",
    async setup(dir) {
      await w(dir, 'package.json', JSON.stringify({ name: 'e', type: 'module', scripts: { test: 'node --test test/*.test.js' } }) + '\n');
      await w(dir, 'src/strings.js', '// Return the input string reversed.\nexport function reverse(s) {\n  // TODO\n}\n');
      await w(dir, 'test/strings.test.js', "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { reverse } from '../src/strings.js';\ntest('reverse', () => { assert.equal(reverse('abc'),'cba'); assert.equal(reverse(''),''); assert.equal(reverse('racecar'),'racecar'); });\n");
    },
    async grade(dir, execFileP) {
      return runsClean(dir, 'npm test', execFileP);
    },
  },
  {
    name: 'precise_edit',
    maxTurns: 8,
    prompt:
      'In src/config.js there is a line `export const TIMEOUT_MS = 1000;`. Change only the number so the timeout is 5000. Do not change anything else in the file.',
    async setup(dir) {
      await w(dir, 'src/config.js', 'export const NAME = "svc";\nexport const TIMEOUT_MS = 1000;\nexport const RETRIES = 3;\n');
    },
    async grade(dir) {
      const text = await readMaybe(dir, 'src/config.js');
      if (text === null) return false;
      return /export const TIMEOUT_MS = 5000;/.test(text)
        && /export const NAME = "svc";/.test(text)
        && /export const RETRIES = 3;/.test(text);
    },
  },
  {
    name: 'grep_and_report',
    maxTurns: 8,
    prompt:
      "Count how many lines across the .js files in src/ contain the text 'TODO'. Use the grep and bash tools. Then write a file TODO_COUNT.txt in the workspace root whose entire contents is just that integer (no extra text).",
    async setup(dir) {
      await w(dir, 'src/a.js', 'export const A = 1; // TODO refactor\n');
      await w(dir, 'src/b.js', 'export const B = 2; // TODO later\nexport const C = 3;\n');
      await w(dir, 'src/c.js', 'export const D = 4; // done\n');
    },
    async grade(dir) {
      const text = await readMaybe(dir, 'TODO_COUNT.txt');
      if (text === null) return false;
      return text.trim() === '2';
    },
  },
];
